--
-- Triggers `centers`
--
DELIMITER $$
CREATE TRIGGER `before_center_insert` BEFORE INSERT ON `centers` FOR EACH ROW BEGIN
    DECLARE next_num INT;
    DECLARE partner_abbr VARCHAR(10);
    
    IF NEW.partner_id IS NOT NULL THEN
        SELECT COALESCE(SUBSTRING(name, 1, 3), 'CTR')
        INTO partner_abbr
        FROM partners 
        WHERE id = NEW.partner_id;
    ELSE
        SET partner_abbr = 'CTR';
    END IF;
    
    IF NEW.center_id IS NULL OR NEW.center_id = '' THEN
        SELECT COALESCE(MAX(CAST(SUBSTRING_INDEX(center_id, '-', -1) AS UNSIGNED)), 0) + 1 
        INTO next_num
        FROM centers 
        WHERE partner_id = NEW.partner_id;
        
        SET NEW.center_id = CONCAT(UPPER(partner_abbr), '-', LPAD(next_num, 3, '0'));
    END IF;
    
    IF NEW.created_at IS NULL THEN
        SET NEW.created_at = NOW();
    END IF;
    IF NEW.updated_at IS NULL THEN
        SET NEW.updated_at = NOW();
    END IF;
END
$$
DELIMITER ;

